use crate::config::App;
use std::fmt::Write as _;
use std::path::Path;

/// Render a complete systemd user unit for one app.
pub fn render(app: &App, env_file: &Path, linger_bin: &Path) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "# Generated by linger. Edit ~/.config/linger/config.toml, then run `linger sync`."
    );

    let _ = writeln!(out, "[Unit]");
    let _ = writeln!(out, "Description=linger: {}", app.name);
    if app.after.is_empty() {
        let _ = writeln!(out, "After=display-manager.service");
    } else {
        let _ = writeln!(out, "After={}", app.after.join(" "));
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "[Service]");
    let _ = writeln!(out, "Type=simple");
    let _ = writeln!(out, "EnvironmentFile={}", env_file.display());
    for entry in &app.env {
        let _ = writeln!(out, "Environment=\"{}\"", escape_env(entry));
    }
    if app.wait_for_x {
        let _ = writeln!(
            out,
            "ExecStartPre={} wait-for-x",
            exec_quote(&linger_bin.to_string_lossy())
        );
    }

    let mut command = exec_quote(&app.command);
    for arg in &app.args {
        command.push(' ');
        command.push_str(&exec_quote(arg));
    }
    let _ = writeln!(out, "ExecStart={command}");
    let _ = writeln!(out, "Restart={}", app.restart.as_systemd());
    let _ = writeln!(out, "RestartSec={}", app.restart_sec);

    let _ = writeln!(out);
    let _ = writeln!(out, "[Install]");
    let _ = writeln!(out, "WantedBy=default.target");

    out
}

/// systemd unquotes ExecStart the same way a shell does for our purposes.
/// Leave simple paths untouched, single-quote anything else.
fn exec_quote(value: &str) -> String {
    const SAFE: &str = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_./:=@%+-";
    if !value.is_empty() && value.chars().all(|c| SAFE.contains(c)) {
        return value.to_string();
    }
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn escape_env(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            other => out.push(other),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::RestartPolicy;
    use std::path::PathBuf;

    fn app() -> App {
        App {
            name: "demo".into(),
            command: "/usr/bin/demo".into(),
            args: vec!["--flag".into(), "two words".into()],
            restart: RestartPolicy::OnFailure,
            restart_sec: 5,
            wait_for_x: true,
            env: vec!["RUST_LOG=debug".into()],
            after: vec!["display-manager.service".into()],
        }
    }

    #[test]
    fn renders_expected_directives() {
        let unit = render(
            &app(),
            Path::new("/home/u/.config/linger/env.conf"),
            Path::new("/home/u/.cargo/bin/linger"),
        );
        assert!(unit.contains("Description=linger: demo"));
        assert!(unit.contains("EnvironmentFile=/home/u/.config/linger/env.conf"));
        assert!(unit.contains("ExecStartPre=/home/u/.cargo/bin/linger wait-for-x"));
        assert!(unit.contains("ExecStart=/usr/bin/demo --flag 'two words'"));
        assert!(unit.contains("Restart=on-failure"));
        assert!(unit.contains("RestartSec=5"));
        assert!(unit.contains("WantedBy=default.target"));
    }

    #[test]
    fn quoting_round_trip_shape() {
        assert_eq!(exec_quote("/usr/bin/xterm"), "/usr/bin/xterm");
        assert_eq!(exec_quote("a b"), "'a b'");
        assert_eq!(exec_quote("it's"), "'it'\\''s'");
    }

    #[test]
    fn no_x_wait_when_disabled() {
        let mut app = app();
        app.wait_for_x = false;
        let unit = render(&app, &PathBuf::from("/e"), &PathBuf::from("/l"));
        assert!(!unit.contains("ExecStartPre"));
    }
}
